create table if not exists triage_events(id uuid primary key,stream_id uuid not null,event_version bigint not null,event_type varchar(120) not null,payload varchar(16000) not null,occurred_at timestamptz not null,constraint uk_triage_stream_version unique(stream_id,event_version)); create index if not exists idx_triage_events_stream on triage_events(stream_id,event_version);
create table if not exists triage_observations(id uuid primary key,visit_id uuid not null,type varchar(120) not null,value double precision not null,unit varchar(40),measured_at timestamptz not null); create index if not exists idx_triage_obs_visit on triage_observations(visit_id,measured_at desc);
create table if not exists processed_events(event_id uuid primary key,consumer_name varchar(120) not null,processed_at timestamptz not null);
alter table outbox_events alter column payload type varchar(16000); alter table outbox_events add column if not exists attempts integer not null default 0; alter table outbox_events add column if not exists next_attempt_at timestamptz; update outbox_events set next_attempt_at=created_at where next_attempt_at is null; alter table outbox_events alter column next_attempt_at set not null; alter table outbox_events add column if not exists last_error varchar(2000);
